const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.sparkles}"/></svg>`;
const tracks=[{title:'파도가 잠든 밤',artist:'NOVA',genre:'Ambient Pop',cover:'ocean',time:'3:42',tag:'EDITOR’S PICK'},{title:'Afterglow',artist:'milo',genre:'Indie Pop',cover:'orange',type:'AFTER<br>GLOW',time:'2:58'},{title:'Blue Hour',artist:'SORA',genre:'Lo-fi / Chill',cover:'blue',type:'blue<br>hour.',time:'3:16'},{title:'너의 궤도',artist:'NOVA',genre:'Alternative R&B',cover:'nova',time:'3:28'},{title:'A Little Closer',artist:'off:beat',genre:'Bedroom Pop',cover:'lime',type:'a little<br>closer.',time:'2:47'}];
function art(t,cls='album-art'){return `<div class="${cls} cover cover-${t.cover}">${cls==='album-art'?`${t.type?`<span class="album-typography">${t.type}</span><span class="cover-micro">${t.artist.toUpperCase()} · ORIGINAL SOUND</span>`:''}${t.tag?`<span class="cover-label">${t.tag}</span>`:''}<span class="album-play">${icon('play')}</span>`:''}</div>`}
function albums(){return `<div class="album-grid">${tracks.map(t=>`<a href="#song" class="album-card">${art(t)}<h3 class="album-title">${t.title}${icon('heart')}</h3><div class="album-meta">${t.artist}<span class="ai-mini">AI</span><span class="dot">·</span>${t.genre}</div></a>`).join('')}</div>`}
function chart(full=false){return `<div class="chart-list ${full?'large-chart':''}">${tracks.slice(0,full?5:3).map((t,i)=>`<div class="chart-row"><span class="chart-number">${i+1}</span><span class="chart-change">${i===2?'–':'↑'}</span>${art(t,'chart-thumb')}<a href="#song" class="chart-song">${t.title}<small>${t.artist} · ${t.genre}</small></a><span class="chart-time">${t.time}</span><button class="icon-button" data-demo="음악 재생" aria-label="${t.title} 재생 시안">${icon('play')}</button></div>`).join('')}</div>`}
function heading(title,sub='',right=''){return `<div class="page-heading"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`}
function section(title,sub='',link='',label='전체 보기'){return `<div class="section-heading"><h2>${title}</h2>${sub?`<span>${sub}</span>`:''}${link?`<a href="#${link}">${label}${icon('chevron')}</a>`:''}</div>`}
const bars=()=>`<div class="sound-bars" aria-hidden="true">${[25,49,77,100,65,110,82,55,29].map(h=>`<span style="--h:${h}px"></span>`).join('')}</div>`;
const tabs=(items)=>`<div class="view-tabs">${items.map((t,i)=>`<button class="${i===0?'selected':''}" data-demo="${t}">${t}</button>`).join('')}</div>`;
const mockTable=(heads,rows)=>`<div class="table-scroll"><table class="simple-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
